// Datos que mandó el panel (el nodo Webhook guarda el cuerpo en .body)
const entrada = $("Webhook").first().json.body || {};
const motoId = String(entrada.moto_id || "");
const instrucciones = String(entrada.instrucciones || "").trim().slice(0, 1000);

if (!motoId) throw new Error("Falta moto_id.");

const catalogo = $input.first().json;
const m = (catalogo.motos || []).find(x => String(x.id) === motoId);

if (!m) throw new Error("No se encontró la moto con id " + motoId);

return [{
  json: {
    instrucciones,
    moto: {
      id: m.id,
      nombre: m.nombre,
      modelo: m.modelo,
      km: m.km,
      precio: m.precio,
      color: m.color,
      descripcion: m.descripcion,
      fotos: m.fotos || [],
      video: m.video || ""
    }
  }
}];

const respuesta = $input.first().json;

const candidato = respuesta.candidates?.[0];
let content = (candidato?.content?.parts || []).map(p => p.text || "").join("").trim();

if (!content) {
  const motivo = candidato?.finishReason || respuesta.promptFeedback?.blockReason || "sin detalle";
  throw new Error("Gemini no devolvió contenido (motivo: " + motivo + ").");
}

// Por si Gemini envuelve el JSON en ```json ... ```
content = content.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");

let r;
try {
  r = JSON.parse(content);
} catch (error) {
  throw new Error("La respuesta de Gemini no es un JSON válido.");
}

if (!r.prompt_video || !r.caption || !Array.isArray(r.hashtags)) {
  throw new Error("La respuesta de Gemini no contiene todos los campos esperados.");
}

const moto = $("Prompt Gemini").first().json.moto;

return [{
  json: {
    ok: true,
    moto: { id: moto.id, nombre: moto.nombre },
    prompt_video: r.prompt_video,
    caption: r.caption,
    hashtags: r.hashtags
  }
}];
